// Build the fetch window: payments for the last N days, settlement recon per day
const cfg = $('Set Recon Rules').first().json;
const lookback = Number(cfg.lookbackDays) || 7;
const reconDays = Number(cfg.reconDays) || 5;
const days = [];
for (let i = 0; i < reconDays; i++) {
  const d = $today.minus({ days: i });
  days.push({ year: d.year, month: d.month, day: d.day, date: d.toISODate() });
}
return [{
  json: {
    fromTs: Math.floor($today.minus({ days: lookback }).toSeconds()),
    toTs: Math.floor($now.toSeconds()),
    settlementFromTs: Math.floor($today.minus({ days: lookback + 7 }).toSeconds()),
    days,
  },
}];

// Core engine: match payments to invoices, roll payments into settlements,
// confirm settlements against bank credits, raise exceptions and plan failed-payment chases.
// Every output item has a `kind` that the router uses.
const cfg = $('Set Recon Rules').first().json;
const nowMs = Date.now();
const todayISO = $today.toISODate();
const nowISO = $now.toISO();
const tol = Number(cfg.amountTolerance) || 1;
const r2 = n => Math.round((Number(n) || 0) * 100) / 100;
const num = v => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const rupees = paise => r2((Number(paise) || 0) / 100);
const tsISO = s => (s ? new Date(s * 1000).toISOString() : '');
const daysAgo = s => (nowMs - s * 1000) / 86400000;
const digits = s => String(s || '').replace(/\D/g, '').slice(-10);
const lower = s => String(s || '').trim().toLowerCase();
const pages = name => { try { return $(name).all().flatMap(i => (Array.isArray(i.json.items) ? i.json.items : [])); } catch (e) { return []; } };
const uniq = (list, key) => Object.values(Object.fromEntries(list.filter(x => x && x[key]).map(x => [x[key], x])));
const FEE_PCT = (() => { try { return JSON.parse(cfg.expectedFeePct || '{}'); } catch (e) { return {}; } })();

// ---------- Inputs ----------
const payments = uniq(pages('Fetch Razorpay Payments'), 'id');
const recon = pages('Fetch Settlement Recon');
const settlements = uniq($input.all().flatMap(i => (Array.isArray(i.json.items) ? i.json.items : [])), 'id');
const invoices = $('Read Invoices').all().map(i => i.json).filter(r => r['Invoice ID']);
const bank = $('Read Bank Credits').all().map(i => i.json).filter(r => r['Amount']);
const ledgerPrev = Object.fromEntries($('Read Payments Ledger').all().map(i => i.json).filter(r => r['Payment ID']).map(r => [String(r['Payment ID']), r]));
const excPrev = Object.fromEntries($('Read Exceptions').all().map(i => i.json).filter(r => r['Exception Key']).map(r => [String(r['Exception Key']), r]));

// ---------- Invoice index ----------
const CLOSED = ['void', 'cancelled', 'canceled', 'written off'];
const inv = {};
const byOrder = {};
for (const r of invoices) {
  const id = String(r['Invoice ID']).trim();
  inv[id] = {
    id, row: r,
    name: r['Customer Name'] || '', email: lower(r['Customer Email']), phone: digits(r['Customer Phone']),
    amount: num(r['Amount']), currency: r['Currency'] || 'INR', dueDate: r['Due Date'] || '',
    closed: CLOSED.includes(lower(r['Status'])),
    prevRecon: String(r['Recon Status'] || ''),
    linkId: String(r['Payment Link ID'] || ''),
    chaseCount: parseInt(r['Chase Count'], 10) || 0,
    lastChaseAt: r['Last Chase Date'] || '',
    captured: [], failed: [], authorized: [],
  };
  if (r['Razorpay Order ID']) byOrder[String(r['Razorpay Order ID']).trim()] = inv[id];
}

// ---------- Recon lines by payment ----------
const reconByEntity = {};
const receiptByPayment = {};
const settlementPayments = {};
for (const l of recon) {
  if (l.type === 'payment' && l.entity_id) {
    reconByEntity[l.entity_id] = l;
    if (l.order_receipt) receiptByPayment[l.entity_id] = String(l.order_receipt);
    if (l.settlement_id) (settlementPayments[l.settlement_id] = settlementPayments[l.settlement_id] || []).push(l.entity_id);
  }
}

// ---------- Match each payment to an invoice ----------
const matchOf = p => {
  const manual = ledgerPrev[p.id] && String(ledgerPrev[p.id]['Manual Invoice ID'] || '').trim();
  if (manual && inv[manual]) return { invoice: inv[manual], method: 'Manual' };
  const notes = p.notes && !Array.isArray(p.notes) ? p.notes : {};
  for (const ref of [notes.invoice_id, notes.invoice, notes.invoiceId, notes.reference_id, receiptByPayment[p.id], p.description]) {
    const k = String(ref || '').trim();
    if (k && inv[k]) return { invoice: inv[k], method: 'Invoice reference' };
  }
  if (p.order_id && byOrder[p.order_id]) return { invoice: byOrder[p.order_id], method: 'Razorpay order' };
  return null;
};
const fuzzyCandidates = p => {
  const amt = rupees(p.amount), e = lower(p.email), ph = digits(p.contact);
  return Object.values(inv)
    .filter(v => !v.closed)
    .map(v => {
      const balance = v.amount - v.captured.reduce((s, x) => s + x.net, 0);
      let score = 0;
      if (e && v.email && e === v.email) score += 3;
      if (ph && v.phone && ph === v.phone) score += 3;
      if (Math.abs(balance - amt) <= tol) score += 2;
      else if (Math.abs(balance - amt) / Math.max(balance, 1) <= 0.05) score += 1;
      return { v, balance: r2(balance), score };
    })
    .filter(c => c.score > 0)
    .sort((a, b) => b.score - a.score);
};

const out = [];
const exceptions = [];
const raise = (type, severity, entity, fields) => {
  const key = `${type}|${entity}`;
  const prev = excPrev[key];
  if (prev && ['resolved', 'ignored'].includes(lower(prev['Status']))) return;
  exceptions.push({
    'Exception Key': key, 'Type': type, 'Severity': severity, 'Entity ID': entity,
    'Invoice ID': fields.invoiceId || '', 'Customer': fields.customer || '', 'Amount': fields.amount ?? '',
    'Detail': fields.detail || '', 'Suggested Action': fields.action || '',
    'First Detected': (prev && prev['First Detected']) || todayISO, 'Last Seen': todayISO,
    'Status': (prev && prev['Status']) || 'Open',
  });
};

const categorize = p => {
  const t = `${p.error_reason || ''} ${p.error_description || ''} ${p.error_code || ''}`.toLowerCase();
  if (/cancel|abandon|closed the|declined by (the )?(customer|user)|rejected by (the )?(customer|user)/.test(t)) return 'cancelled';
  if (/insufficient|balance/.test(t)) return 'insufficient_funds';
  if (/limit|exceed/.test(t)) return 'limit_exceeded';
  if (/pin|otp|authenticat|incorrect|invalid (vpa|upi)|vpa.*invalid|expired card|card.*invalid/.test(t)) return 'details_incorrect';
  if (/timed? ?out|timeout|expired/.test(t)) return 'timeout';
  if (/bank|server|technical|gateway|down|unavailable|network/.test(t) || ['bank', 'gateway'].includes(p.error_source)) return 'bank_issue';
  return 'other';
};

const methodStats = {};
const ledgerRows = [];
const unmatchedForAI = [];
let gross = 0, fees = 0, taxes = 0;

for (const p of payments) {
  const method = p.method || 'unknown';
  const ms = methodStats[method] || (methodStats[method] = { captured: 0, failed: 0 });
  const m = matchOf(p);
  const rl = reconByEntity[p.id];
  const net = rupees(p.amount - (p.amount_refunded || 0));
  let note = '', failureCategory = '';

  if (p.status === 'captured' || p.status === 'refunded') {
    ms.captured++;
    gross += rupees(p.amount); fees += rupees(p.fee); taxes += rupees(p.tax);
    const rec = { id: p.id, net, method, created: p.created_at, settled: !!(rl && rl.settled), settlementId: rl ? rl.settlement_id : '',
      utr: rl ? rl.settlement_utr : '', settledAt: rl && rl.settled_at ? tsISO(rl.settled_at) : '', fee: rupees(p.fee), tax: rupees(p.tax),
      onHold: !!(rl && rl.on_hold) };
    if (m) { m.invoice.captured.push(rec); note = `Matched by ${m.method}`; }
    else {
      const cands = fuzzyCandidates(p);
      const strong = cands.filter(c => c.score >= 5);
      if (strong.length === 1) {
        note = 'Probable match, needs confirmation';
        raise('Probable Match', 'Medium', p.id, { invoiceId: strong[0].v.id, customer: strong[0].v.name, amount: net,
          detail: `Same customer and amount as open invoice ${strong[0].v.id}, but no invoice reference on the payment`,
          action: `Confirm and type ${strong[0].v.id} in "Manual Invoice ID" on the Payments Ledger row` });
      } else if (cands.length) {
        note = 'Unmatched, sent for AI suggestion';
        unmatchedForAI.push({ kind: 'unmatched', paymentId: p.id, amount: net, currency: p.currency, method, email: p.email || '',
          contact: p.contact || '', vpa: p.vpa || (p.upi && p.upi.vpa) || '', description: p.description || '',
          notes: JSON.stringify(p.notes || {}), createdAt: tsISO(p.created_at),
          candidates: cands.slice(0, 15).map(c => ({ invoiceId: c.v.id, customer: c.v.name, email: c.v.email, balance: c.balance, dueDate: c.v.dueDate })),
          exceptionKey: `Unmatched Payment|${p.id}`,
          prevStatus: excPrev[`Unmatched Payment|${p.id}`] ? excPrev[`Unmatched Payment|${p.id}`]['Status'] : '',
          firstDetected: excPrev[`Unmatched Payment|${p.id}`] ? excPrev[`Unmatched Payment|${p.id}`]['First Detected'] : todayISO });
      } else {
        note = 'Unmatched, no candidate invoice';
        raise('Unmatched Payment', net >= cfg.highValueAmount ? 'High' : 'Medium', p.id, { customer: p.email || p.contact, amount: net,
          detail: `${method} payment with no invoice reference and no similar open invoice`, action: 'Identify the customer and add the invoice ID in "Manual Invoice ID"' });
      }
    }
    // Settlement checks
    if (rec.onHold) raise('Payment On Hold', 'High', p.id, { invoiceId: m ? m.invoice.id : '', amount: net, detail: 'Razorpay has put this payment on hold', action: 'Check the Razorpay dashboard or contact support' });
    else if (!rec.settled && daysAgo(p.created_at) > cfg.settlementSlaDays)
      raise('Settlement Delayed', 'Medium', p.id, { invoiceId: m ? m.invoice.id : '', amount: net,
        detail: `Captured ${Math.floor(daysAgo(p.created_at))} days ago and not settled yet`, action: 'Check settlement schedule or raise a ticket with Razorpay' });
    // Fee check (Razorpay fee includes GST; compare the pre-tax part)
    const pct = FEE_PCT[method];
    if (cfg.checkFees && pct !== undefined && p.fee) {
      const expected = rupees(p.amount) * pct / 100;
      const actual = rupees(p.fee - (p.tax || 0));
      if (actual > expected * 1.05 + 1)
        raise('Fee Above Expected', 'Low', p.id, { invoiceId: m ? m.invoice.id : '', amount: net,
          detail: `Fee Rs. ${actual} vs expected Rs. ${r2(expected)} at ${pct}% for ${method}`, action: 'Compare against your Razorpay pricing plan' });
    }
  } else if (p.status === 'failed') {
    ms.failed++;
    failureCategory = categorize(p);
    if (m) m.invoice.failed.push({ ...p, failureCategory });
    note = m ? `Failed (${failureCategory})` : `Failed (${failureCategory}), no invoice reference`;
  } else if (p.status === 'authorized') {
    if (m) m.invoice.authorized.push(p);
    if (daysAgo(p.created_at) > 1)
      raise('Authorized Not Captured', 'High', p.id, { invoiceId: m ? m.invoice.id : '', amount: rupees(p.amount),
        detail: 'Payment authorized but not captured; Razorpay auto-refunds uncaptured payments', action: 'Capture it in Razorpay or enable auto-capture' });
  }

  ledgerRows.push({
    kind: 'ledger',
    'Payment ID': p.id, 'Created At': tsISO(p.created_at), 'Status': p.status, 'Method': method,
    'Amount': rupees(p.amount), 'Refunded': rupees(p.amount_refunded), 'Fee': rupees(p.fee), 'GST on Fee': rupees(p.tax),
    'Customer Email': p.email || '', 'Customer Contact': p.contact || '', 'VPA': p.vpa || (p.upi && p.upi.vpa) || '',
    'Invoice ID': m ? m.invoice.id : '', 'Match Method': m ? m.method : '', 'Order ID': p.order_id || '',
    'Settlement ID': rl ? rl.settlement_id || '' : '', 'UTR': rl ? rl.settlement_utr || '' : '',
    'Settled At': rl && rl.settled_at ? tsISO(rl.settled_at) : '',
    'Error Code': p.error_code || '', 'Error Reason': p.error_reason || p.error_description || '',
    'Failure Category': failureCategory, 'Recon Note': note, 'Updated On': nowISO,
  });
}

// ---------- Settlements vs bank credits ----------
const bankRows = bank.map(b => ({ amount: num(b['Amount']), text: `${b['UTR'] || ''} ${b['Reference'] || ''} ${b['Narration'] || ''}`.toUpperCase(), date: b['Date'] || '' }));
const bankStatus = {};
const settlementRows = [];
for (const s of settlements) {
  const amt = rupees(s.amount);
  let status = 'Bank check skipped', bankDate = '';
  if (s.status === 'failed') {
    status = 'Settlement failed';
    raise('Settlement Failed', 'High', s.id, { amount: amt, detail: 'Razorpay could not transfer this settlement', action: 'Check the bank account on Razorpay and contact support' });
  } else if (bankRows.length && s.status === 'processed') {
    const hit = bankRows.find(b => s.utr && b.text.includes(String(s.utr).toUpperCase()) && Math.abs(b.amount - amt) <= tol)
      || bankRows.find(b => s.utr && b.text.includes(String(s.utr).toUpperCase()));
    if (hit && Math.abs(hit.amount - amt) <= tol) { status = 'Bank confirmed'; bankDate = hit.date; }
    else if (hit) {
      status = 'Amount differs in bank';
      raise('Bank Amount Mismatch', 'High', s.id, { amount: amt, detail: `Bank shows ${hit.amount} for UTR ${s.utr}, Razorpay settled ${amt}`, action: 'Check for bank charges or a partial credit' });
    } else if (daysAgo(s.created_at) > cfg.bankCreditSlaDays) {
      status = 'Not found in bank';
      raise('Settlement Not in Bank', 'High', s.id, { amount: amt, detail: `UTR ${s.utr || '(none)'} not found in Bank Credits ${Math.floor(daysAgo(s.created_at))} days after settlement`, action: 'Update the Bank Credits tab or ask the bank to trace the UTR' });
    } else status = 'Awaiting bank credit';
  } else if (s.status !== 'processed') status = `Razorpay status: ${s.status}`;
  bankStatus[s.id] = status;
  settlementRows.push({
    kind: 'settlement', 'Settlement ID': s.id, 'Created On': tsISO(s.created_at), 'Amount': amt,
    'Fees': rupees(s.fees), 'GST on Fees': rupees(s.tax), 'UTR': s.utr || '', 'Razorpay Status': s.status,
    'Payments': (settlementPayments[s.id] || []).length, 'Bank Status': status, 'Bank Date': bankDate, 'Updated On': nowISO,
  });
}

// ---------- Invoice outcomes, receipts, link cancels, chases ----------
const invoiceRows = [], receipts = [], cancels = [], chases = [];
const PAID = ['Reconciled', 'Settled - awaiting bank', 'Paid - awaiting settlement', 'Overpaid'];
const counts = { paidToday: 0, partial: 0, overpaid: 0, chases: 0 };

for (const v of Object.values(inv)) {
  if (v.closed) continue;
  const paid = r2(v.captured.reduce((s, x) => s + x.net, 0));
  const balance = r2(v.amount - paid);
  const touched = v.captured.length || v.failed.length || v.authorized.length;
  if (!touched) continue;

  let recon = 'Open';
  if (paid > 0) {
    const allSettled = v.captured.every(x => x.settled);
    const allBank = allSettled && v.captured.every(x => bankStatus[x.settlementId] === 'Bank confirmed');
    if (balance < -tol) recon = 'Overpaid';
    else if (balance > tol) recon = 'Partially Paid';
    else recon = allBank ? 'Reconciled' : allSettled ? 'Settled - awaiting bank' : 'Paid - awaiting settlement';
    if (recon === 'Overpaid') {
      counts.overpaid++;
      raise('Overpaid', 'Medium', v.id, { invoiceId: v.id, customer: v.name, amount: -balance, detail: `Received ${paid} against ${v.amount}`, action: 'Refund the excess or apply it as credit' });
    }
    const full = v.captured.filter(x => x.net >= v.amount - tol);
    if (full.length >= 2)
      raise('Duplicate Payment', 'High', v.id, { invoiceId: v.id, customer: v.name, amount: r2(full.slice(1).reduce((s, x) => s + x.net, 0)),
        detail: `${full.length} full payments: ${full.map(x => x.id).join(', ')}`, action: 'Refund the duplicate payment from Razorpay' });
    if (recon === 'Partially Paid') counts.partial++;
  } else if (v.failed.length) recon = 'Payment Failed';

  const nowPaid = PAID.includes(recon) && !PAID.includes(v.prevRecon);
  if (nowPaid) counts.paidToday++;
  const last = v.captured.slice().sort((a, b) => b.created - a.created)[0];
  const settledDates = v.captured.map(x => x.settledAt).filter(Boolean).sort();

  invoiceRows.push({
    kind: 'invoice', 'Invoice ID': v.id,
    'Status': PAID.includes(recon) ? 'Paid' : recon === 'Partially Paid' ? 'Partially Paid' : v.row['Status'] || 'Open',
    'Paid Amount': paid, 'Balance Due': Math.max(balance, 0),
    'Payment IDs': v.captured.map(x => x.id).join(', '),
    'Payment Method': [...new Set(v.captured.map(x => x.method))].join(', '),
    'Paid On': last ? tsISO(last.created).slice(0, 10) : '',
    'Settlement ID': [...new Set(v.captured.map(x => x.settlementId).filter(Boolean))].join(', '),
    'UTR': [...new Set(v.captured.map(x => x.utr).filter(Boolean))].join(', '),
    'Settled On': settledDates.length ? settledDates[settledDates.length - 1].slice(0, 10) : '',
    'Fee': r2(v.captured.reduce((s, x) => s + x.fee, 0)), 'GST on Fee': r2(v.captured.reduce((s, x) => s + x.tax, 0)),
    'Net Received': r2(paid - v.captured.reduce((s, x) => s + x.fee, 0)),
    'Recon Status': recon, 'Last Recon Run': nowISO,
  });

  if (nowPaid && v.email && last) receipts.push({ kind: 'receipt', invoiceId: v.id, customerName: v.name, email: v.email, amount: paid,
    currency: v.currency, paymentId: last.id, method: last.method, paidOn: tsISO(last.created).slice(0, 10) });
  if (PAID.includes(recon) && v.linkId) cancels.push({ kind: 'cancel_link', linkId: v.linkId, invoiceId: v.id, reason: 'Invoice paid' });

  // Failed-payment chase
  if (balance > tol && v.failed.length) {
    const lastFail = v.failed.slice().sort((a, b) => b.created_at - a.created_at)[0];
    const lastSuccess = last ? last.created : 0;
    const lastChaseMs = v.lastChaseAt ? new Date(v.lastChaseAt).getTime() || 0 : 0;
    const hoursSinceChase = lastChaseMs ? (nowMs - lastChaseMs) / 3600000 : Infinity;
    const failMs = lastFail.created_at * 1000;
    const graceOver = (nowMs - failMs) / 60000 >= cfg.retryGraceMinutes;
    const newFailure = failMs > lastChaseMs;
    const followUpDue = v.chaseCount > 0 && hoursSinceChase >= cfg.chaseIntervalDays * 24;
    const eligible = lastFail.created_at > lastSuccess && graceOver && hoursSinceChase >= cfg.minHoursBetweenChases && (newFailure || followUpDue);
    if (eligible && v.chaseCount >= cfg.maxChaseAttempts) {
      raise('Chase Exhausted', 'High', v.id, { invoiceId: v.id, customer: v.name, amount: balance,
        detail: `${v.chaseCount} payment-failure reminders sent, still unpaid. Last failure: ${lastFail.error_description || lastFail.failureCategory}`, action: 'Call the customer or offer bank transfer' });
    } else if (eligible && v.email) {
      counts.chases++;
      const attempt = v.chaseCount + 1;
      if (v.linkId) cancels.push({ kind: 'cancel_link', linkId: v.linkId, invoiceId: v.id, reason: 'Replaced by a new link' });
      const customer = { name: v.name || 'Customer', email: v.email };
      if (v.phone) customer.contact = v.phone;
      chases.push({
        kind: 'chase', invoiceId: v.id, prevChaseAt: v.lastChaseAt, customerName: v.name, email: v.email, balance, currency: v.currency, dueDate: v.dueDate,
        attempt, failureCategory: lastFail.failureCategory, failureText: lastFail.error_description || lastFail.error_reason || '',
        failedMethod: lastFail.method || '', failedAttempts: v.failed.length, prevLinkId: v.linkId,
        escalate: attempt >= cfg.maxChaseAttempts || balance >= cfg.highValueAmount,
        linkPayload: {
          amount: Math.round(balance * 100), currency: v.currency || 'INR', accept_partial: false,
          description: `Payment for invoice ${v.id}`.slice(0, 2048),
          reference_id: `${v.id}-R${attempt}-${nowMs.toString(36)}`.slice(0, 40),
          expire_by: Math.floor(nowMs / 1000) + (Number(cfg.linkExpiryDays) || 7) * 86400,
          customer, notify: { sms: false, email: false }, reminder_enable: false,
          notes: { invoice_id: v.id, chase_attempt: String(attempt), source: 'n8n-reconciler' },
        },
      });
    }
  }
}

const summary = {
  kind: 'summary', runAt: nowISO, periodDays: cfg.lookbackDays,
  payments: payments.length, gross: r2(gross), fees: r2(fees), taxes: r2(taxes),
  settlements: settlements.length, settledAmount: r2(settlements.reduce((s, x) => s + rupees(x.amount), 0)),
  bankConfirmed: Object.values(bankStatus).filter(s => s === 'Bank confirmed').length,
  invoicesTouched: invoiceRows.length, ...counts,
  unmatchedForAI: unmatchedForAI.length,
  methodStats,
  failureMix: payments.filter(p => p.status === 'failed').reduce((m, p) => { const c = categorize(p); m[c] = (m[c] || 0) + 1; return m; }, {}),
  exceptions: exceptions.filter(e => e.Status === 'Open'),
};

return [
  ...unmatchedForAI,
  ...exceptions.map(e => ({ kind: 'exception', ...e })),
  ...ledgerRows, ...settlementRows, ...invoiceRows, ...receipts,
  ...uniq(cancels, 'linkId'), ...chases, summary,
].map(j => ({ json: j }));

