// Validate the AI suggestion; it is only ever a suggestion written to Exceptions
const out = [];
$input.all().forEach((item, i) => {
  const u = $('Reconcile Payments & Settlements').itemMatching(i).json;
  if (['resolved', 'ignored'].includes(String(u.prevStatus || '').toLowerCase())) return;
  let f = item.json.message && item.json.message.content;
  if (typeof f === 'string') { try { f = JSON.parse(f); } catch (e) { f = null; } }
  const valid = new Set(u.candidates.map(c => c.invoiceId));
  const pick = f && valid.has(String(f.invoiceId)) ? String(f.invoiceId) : '';
  const conf = f ? Number(f.confidence) || 0 : 0;
  const cand = u.candidates.find(c => c.invoiceId === pick);
  out.push({
    json: {
      'Exception Key': u.exceptionKey, 'Type': 'Unmatched Payment', 'Severity': u.amount >= $('Set Recon Rules').first().json.highValueAmount ? 'High' : 'Medium',
      'Entity ID': u.paymentId, 'Invoice ID': pick, 'Customer': u.email || u.contact || u.vpa, 'Amount': u.amount,
      'Detail': `${u.method} payment on ${u.createdAt.slice(0, 10)} with no invoice reference` + (pick ? `. AI suggests ${pick} (${cand.customer}, balance ${cand.balance}), confidence ${conf}: ${f.reason || ''}` : '. AI found no confident match.'),
      'Suggested Action': pick && conf >= 0.8 ? `Verify, then type ${pick} in "Manual Invoice ID" on the Payments Ledger row` : 'Identify the customer and add the invoice ID in "Manual Invoice ID"',
      'First Detected': u.firstDetected || $today.toISODate(), 'Last Seen': $today.toISODate(), 'Status': u.prevStatus || 'Open',
      aiPick: pick, aiConfidence: conf,
    },
    pairedItem: { item: i },
  });
});
return out;

