// Record what happened for each chase. A failed send does not count as an attempt.
const nowISO = $now.toISO();
const out = [];
$input.all().forEach((item, i) => {
  const c = $('Reconcile Payments & Settlements').itemMatching(i).json;
  const link = $('Create Payment Link').itemMatching(i).json;
  const sent = !item.json.error;
  out.push({
    json: {
      invoiceId: c.invoiceId, customerName: c.customerName, email: c.email, balance: c.balance, currency: c.currency,
      attempt: c.attempt, failureCategory: c.failureCategory, failureText: c.failureText,
      chaseCount: sent ? c.attempt : c.attempt - 1,
      lastChaseAt: sent ? nowISO : (c.prevChaseAt || ''),
      stage: sent ? `Failure reminder ${c.attempt}` : `Reminder ${c.attempt} failed to send`,
      linkId: link.id || c.prevLinkId || '', linkUrl: link.short_url || '',
      linkExpires: link.expire_by ? new Date(link.expire_by * 1000).toISOString().slice(0, 10) : '',
      sent, escalate: sent && c.escalate,
    },
    pairedItem: { item: i },
  });
});
return out;

