parameters.jsCode:
// Daily reconciliation report (email) and a short Slack digest
const cfg = $('Set Recon Rules').first().json;
const s = $input.first().json;
let ai = [], chases = [];
try { ai = $('Attach AI Match Suggestions').all().map(i => i.json); } catch (e) {}
try { chases = $('Prepare Chase Log').all().map(i => i.json); } catch (e) {}
const inr = n => 'Rs. ' + Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const td = 'style="padding:6px 8px;border-bottom:1px solid #eee;vertical-align:top"';
const SEV = { High: 0, Medium: 1, Low: 2 };
const exc = s.exceptions.slice().sort((a, b) => SEV[a.Severity] - SEV[b.Severity] || (b.Amount || 0) - (a.Amount || 0));
const high = exc.filter(e => e.Severity === 'High');
const rate = m => { const t = m.captured + m.failed; return t ? Math.round((m.captured / t) * 100) + '%' : '-'; };
const methods = Object.entries(s.methodStats).map(([k, m]) => `<tr><td ${td}>${esc(k)}</td><td ${td}>${m.captured}</td><td ${td}>${m.failed}</td><td ${td}>${rate(m)}</td></tr>`).join('');
const sent = chases.filter(c => c.sent);
const aiHits = ai.filter(a => a.aiPick && a.aiConfidence >= 0.8);

const html = `<div style="font-family:Arial,sans-serif;max-width:760px;color:#222">
<h2 style="margin-bottom:4px">Razorpay reconciliation - ${$today.toFormat('d LLL yyyy')}</h2>
<p style="color:#777;margin-top:0">Last ${s.periodDays} days of payments</p>
<p><b>${inr(s.gross)}</b> captured across ${s.payments} payment attempt(s). Fees ${inr(s.fees)} (incl. GST ${inr(s.taxes)}).
${s.settlements} settlement(s) worth ${inr(s.settledAmount)}, ${s.bankConfirmed} confirmed in the bank.</p>
<p>${s.paidToday} invoice(s) newly paid, ${s.partial} partially paid, ${s.overpaid} overpaid.
${sent.length} failed-payment reminder(s) sent with fresh payment links. ${aiHits.length} unmatched payment(s) have a confident AI match suggestion.</p>
${high.length ? `<p style="color:#b91c1c"><b>${high.length} high-severity exception(s) need attention today.</b></p>` : ''}
<h3>Success rate by method</h3>
<table style="border-collapse:collapse"><tr style="background:#f5f5f5"><th align="left" ${td}>Method</th><th align="left" ${td}>Captured</th><th align="left" ${td}>Failed</th><th align="left" ${td}>Success</th></tr>${methods}</table>
<p style="font-size:13px">Failure mix: ${Object.entries(s.failureMix).map(([k, v]) => `${esc(k.replace(/_/g, ' '))} ${v}`).join(', ') || 'none'}</p>
<h3>Open exceptions</h3>
${exc.length ? `<table style="border-collapse:collapse;width:100%"><tr style="background:#f5f5f5"><th align="left" ${td}>Severity</th><th align="left" ${td}>Type</th><th align="left" ${td}>Reference</th><th align="left" ${td}>Detail / action</th><th align="right" ${td}>Amount</th></tr>
${exc.slice(0, 40).map(e => `<tr><td ${td}>${esc(e.Severity)}</td><td ${td}>${esc(e.Type)}</td><td ${td}>${esc(e['Invoice ID'] || e['Entity ID'])}</td><td ${td}>${esc(e.Detail)}<br><span style="color:#777;font-size:12px">${esc(e['Suggested Action'])}</span></td><td ${td} align="right">${e.Amount === '' ? '' : inr(e.Amount)}</td></tr>`).join('')}</table>` : '<p>None.</p>'}
<p style="color:#777;font-size:12px">Details: Payments Ledger, Settlements and Exceptions tabs. Unmatched-payment AI suggestions are listed in Exceptions.</p></div>`;

const slack = [
  `:bank: *Razorpay recon - ${$today.toFormat('d LLL')}*`,
  `Captured ${inr(s.gross)} | Settled ${inr(s.settledAmount)} (${s.bankConfirmed}/${s.settlements} bank-confirmed) | Fees ${inr(s.fees)}`,
  `Paid today: ${s.paidToday} | Partial: ${s.partial} | Failure reminders sent: ${sent.length}`,
  `UPI success rate: ${s.methodStats.upi ? rate(s.methodStats.upi) : 'n/a'}`,
  high.length ? `:rotating_light: *${high.length} high-severity exception(s):*\n${high.slice(0, 8).map(e => `- ${e.Type}: ${e['Invoice ID'] || e['Entity ID']} ${e.Amount === '' ? '' : inr(e.Amount)}`).join('\n')}` : ':white_check_mark: No high-severity exceptions',
].join('\n');

return [{ json: { subject: `Razorpay recon ${$today.toFormat('d LLL')}: ${inr(s.gross)} captured, ${exc.length} open exception(s)`, html, slack } }];
